WITH base AS (SELECT *, CONCAT_WS('-', channel, promo_code) AS channel_promo_code_key, COALESCE(channel, 'N/A') AS resolved_channel FROM promotions WHERE starts_on > DATE '2023-07-09') SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, channel_promo_code_key, resolved_channel, NTILE(10) OVER (PARTITION BY channel ORDER BY discount_pct DESC, id) AS discount_pct_bucket, AVG(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_avg_discount_pct FROM base;
